-- +goose Up

CREATE TABLE lp_rec_pr_attempts (
  tenant_id TEXT NOT NULL REFERENCES tenants (id),
  id TEXT NOT NULL,
  rec_id TEXT NOT NULL CHECK (length(rec_id) BETWEEN 1 AND 64),
  repo TEXT NOT NULL CHECK (length(repo) <= 201),
  created_by TEXT NOT NULL,
  created_at TEXT NOT NULL,
  PRIMARY KEY (tenant_id, id)
);
CREATE INDEX lp_rec_pr_attempts_created ON lp_rec_pr_attempts (tenant_id, created_at);
